import numpy as np
import time


def R_of(h):
    h = np.asarray(h, dtype=float)
    if h.ndim != 1 or h.size == 0:
        return -1.0
    if not np.all(np.isfinite(h)) or np.any(h < 0):
        return -1.0
    s = h.sum()
    if s <= 0:
        return -1.0
    c = np.convolve(h, h)
    L = np.concatenate(([0.0], c, [0.0]))
    L2 = L * L
    cross = L[:-1] * L[1:]
    num = (L2[:-1].sum() + cross.sum() + L2[1:].sum()) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return -1.0
    return num / den


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = budget_seconds - max(1.0, 0.1 * budget_seconds)

    def time_left():
        return deadline - (time.process_time() - t0)

    best = None
    best_r = -1.0

    if start is not None:
        s = np.asarray(start, dtype=float).ravel()
        if s.size > 0 and np.all(np.isfinite(s)) and np.all(s >= 0) and s.sum() > 0 and s.size <= 50000:
            best = s.copy()
            best_r = R_of(best)

    if best is None:
        best = np.ones(50)
        best_r = R_of(best)

    rng = np.random.default_rng(12345)

    def try_candidate(h):
        nonlocal best, best_r
        h = np.asarray(h, dtype=float)
        if h.size == 0 or h.size > 50000:
            return
        if not np.all(np.isfinite(h)) or np.any(h < 0) or h.sum() <= 0:
            return
        r = R_of(h)
        if r > best_r:
            best_r = r
            best = h.copy()

    # The optimal shape is likely a smooth bump with some power p.
    # Try resampling current best to other lengths first (cheap, high-value).
    if best is not None and best.size > 1:
        for M in [50, 75, 100, 150, 200, 250, 300, 400, 500]:
            if time_left() < 0.5:
                break
            if M == best.size:
                continue
            x_old = np.linspace(0, 1, best.size)
            x_new = np.linspace(0, 1, M)
            try_candidate(np.interp(x_new, x_old, best))
        # Also try expanding/contracting the support.
        for scale in [0.7, 0.85, 1.15, 1.3]:
            if time_left() < 0.5:
                break
            M = int(round(best.size * scale))
            if 1 <= M <= 50000:
                x_old = np.linspace(0, 1, best.size)
                x_new = np.linspace(0, 1, M)
                try_candidate(np.interp(x_new, x_old, best))

    # Parametric families: power bumps.
    for N in [50, 100, 150, 200, 250, 300, 400]:
        if time_left() < 1.0:
            break
        x = np.linspace(-1, 1, N)
        for p in [0.5, 0.75, 1.0, 1.5, 2.0, 2.5, 3.0, 4.0]:
            w = np.clip(1 - np.abs(x) ** p, 0, None)
            if w.sum() > 0:
                try_candidate(w)
        for sig in [0.15, 0.25, 0.35, 0.5]:
            w = np.exp(-0.5 * (x / sig) ** 2)
            try_candidate(w)
        try_candidate(np.cos(0.5 * np.pi * x) ** 2)

    # Local hill climbing from best. Perturbation of the best found so far.
    cur = best.copy()
    cur_r = best_r
    step = 0.1
    it = 0
    while time_left() > 0.5:
        it += 1
        if it % 300 == 0:
            step *= 0.95
            if step < 1e-4:
                step = 0.05

        N = cur.size
        mode = rng.integers(0, 5)
        cand = cur.copy()
        if mode == 0:
            k = max(1, N // 8)
            idx = rng.integers(0, N, size=k)
            cand[idx] *= (1.0 + step * rng.standard_normal(k))
        elif mode == 1:
            k = max(1, N // 8)
            idx = rng.integers(0, N, size=k)
            cand[idx] += step * rng.standard_normal(k) * (cand.mean() + 1e-12)
        elif mode == 2:
            a = rng.integers(0, N)
            b = min(N, a + max(1, N // 5))
            cand[a:b] *= (1.0 + step * rng.standard_normal())
        elif mode == 3:
            x = np.linspace(0, 1, N)
            freq = rng.uniform(0.5, 5.0)
            ph = rng.uniform(0, 2 * np.pi)
            cand *= (1.0 + step * np.sin(2 * np.pi * freq * x + ph))
        else:
            # single-entry perturbation
            idx = rng.integers(0, N)
            cand[idx] += step * rng.standard_normal() * (cand.mean() + 1e-12)

        cand = np.clip(cand, 0, None)
        if cand.sum() <= 0:
            continue
        r = R_of(cand)
        if r > cur_r:
            cur = cand
            cur_r = r
            if r > best_r:
                best = cand.copy()
                best_r = r
        elif rng.random() < 0.02:
            # occasional acceptance of worse to escape local optima
            cur = cand
            cur_r = r

    # Final length scan on the best result.
    if time_left() > 0.2 and best.size > 1:
        for M in [50, 100, 150, 200, 250, 300, 400, 500, 750, 1000]:
            if time_left() <= 0:
                break
            if M == best.size:
                continue
            x_old = np.linspace(0, 1, best.size)
            x_new = np.linspace(0, 1, M)
            try_candidate(np.interp(x_new, x_old, best))

    best = np.asarray(best, dtype=float)
    best = np.clip(best, 0, None)
    if best.sum() <= 0:
        best = np.ones(50)
    return best

