def _R(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return -1.0
    c = np.convolve(h, h)
    L = np.empty(c.size + 2)
    L[0] = 0.0
    L[-1] = 0.0
    L[1:-1] = c
    mx = L.max()
    if mx <= 0:
        return -1.0
    a = L[:-1]
    b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    return num / (s * s * mx)


def _resample(h, N):
    x_old = np.linspace(0, 1, h.size)
    x_new = np.linspace(0, 1, N)
    return np.interp(x_new, x_old, h)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85

    def left():
        return deadline - time.process_time()

    rng = np.random.default_rng(1357911)

    # ---- seed ----
    if start is not None:
        h = np.maximum(np.asarray(start, dtype=float).ravel(), 0.0).copy()
        if h.sum() <= 0:
            h = np.ones(50)
    else:
        h = np.ones(50)

    # Work at a higher resolution; the parabola-like optimum is well resolved.
    N = 1200
    if h.size != N:
        h = _resample(h, N)
    best = h.copy()
    best_r = _R(best)

    # ---- coordinate ascent with adaptive step ----
    # Uses full-array vectorised "try all single-coordinate moves" via a
    # cheap trick: for each coordinate try +/-step, accept best improvement.
    n = best.size
    step = 0.05 * max(best.max(), 1e-9)
    order = np.arange(n)

    while left() > 0.0:
        improved = False
        rng.shuffle(order)
        for idx in order:
            if left() <= 0.0:
                break
            old = best[idx]
            best_local = best_r
            best_val = old
            for d in (step, -step, 0.5 * step, -0.5 * step):
                nv = old + d
                if nv < 0:
                    nv = 0.0
                if nv == old:
                    continue
                best[idx] = nv
                r = _R(best)
                if r > best_local:
                    best_local = r
                    best_val = nv
            best[idx] = best_val
            if best_local > best_r:
                best_r = best_local
                improved = True
        if not improved:
            step *= 0.55
            if step < 1e-6 * max(best.max(), 1e-9):
                # perturb and restart
                best = np.maximum(best * (1.0 + 0.02 * rng.standard_normal(n)), 0)
                best_r = _R(best)
                step = 0.03 * max(best.max(), 1e-9)
        else:
            step = min(step * 1.05, 0.1 * max(best.max(), 1e-9))

    return np.asarray(best, dtype=float)

