def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    def tl():
        return time.process_time() < deadline

    rng = np.random.default_rng(20240102 + int(budget_seconds * 1000))

    best = None
    bestR = -1.0

    def consider(h):
        nonlocal best, bestR
        h = np.asarray(h, dtype=float).ravel()
        if h.size == 0 or h.size > 50000:
            return False
        h = np.maximum(h, 0)
        if h.sum() <= 0:
            return False
        r = _R(h)
        if r > bestR:
            bestR = r
            best = h.copy()
            return True
        return False

    if start is not None:
        consider(start)

    # Smooth seeds: parametrize by a power bump with a plateau (super-gaussian).
    def bump(N, p, q):
        x = np.linspace(-1, 1, N)
        return np.clip(1 - np.abs(x) ** p, 0, None) ** q

    for N in (100, 150, 200, 250, 300):
        for p in (1.0, 1.5, 2.0, 3.0, 4.0):
            for q in (0.5, 1.0, 1.5, 2.0):
                consider(bump(N, p, q))
        x = np.linspace(-1, 1, N)
        consider(np.exp(-3 * x**2))
        consider(np.exp(-6 * x**2))
        consider(np.cos(0.5 * np.pi * x) ** 2)
        consider(np.ones(N))

    # Coordinate descent with shrinking step, plus block coordinate moves.
    def optimize(seed, dl):
        h = np.maximum(np.asarray(seed, dtype=float).copy(), 0)
        cur = _R(h)
        n = h.size
        scale = max(h.max(), 1e-9)
        step = 0.35 * scale
        order = np.arange(n)
        while time.process_time() < dl:
            improved = False
            rng.shuffle(order)
            for idx in order:
                if time.process_time() >= dl:
                    break
                old = h[idx]
                for d in (step, -step, step * 0.3, -step * 0.3):
                    nv = old + d
                    if nv < 0:
                        nv = 0.0
                    if nv == old:
                        continue
                    h[idx] = nv
                    r = _R(h)
                    if r > cur:
                        cur = r
                        old = nv
                        improved = True
                    else:
                        h[idx] = old
            # block move: perturb a contiguous block multiplicatively
            if time.process_time() < dl:
                for _ in range(3):
                    a = rng.integers(0, n)
                    b = min(n, a + max(1, n // 6))
                    trial = h.copy()
                    trial[a:b] *= (1.0 + step / scale * rng.standard_normal(b - a))
                    trial = np.maximum(trial, 0)
                    r = _R(trial)
                    if r > cur:
                        h, cur = trial, r
                        improved = True
                        break
            if not improved:
                step *= 0.55
                if step < 1e-5 * scale:
                    # local restart around best
                    h = np.maximum(h * (1.0 + 0.02 * rng.standard_normal(n)), 0)
                    cur = _R(h)
                    step = 0.25 * scale
        return h, cur

    # Optimize current best.
    if best is not None and tl():
        h, cur = optimize(best, deadline)
        if cur > bestR:
            best, bestR = h, cur

    # Resample best to other N and re-optimize the best candidate found.
    while tl():
        base = best.copy()
        N0 = base.size
        trials = []
        for M in (100, 150, 200, 250, 300, 400):
            if M == N0:
                continue
            xi = np.linspace(0, 1, N0)
            xo = np.linspace(0, 1, M)
            trials.append(np.interp(xo, xi, base))
        # also try slightly reshaped bumps
        for N in (200, 250, 300):
            trials.append(bump(N, 2.0, 1.0))
            trials.append(bump(N, 1.5, 1.0))
        got = False
        for t in trials:
            if not tl():
                break
            if consider(t):
                got = True
        if not tl():
            break
        # optimize from the best candidate found
        h, cur = optimize(best, deadline)
        if cur > bestR:
            best, bestR = h, cur
        if not got and not tl():
            break
        # one more quick pass; then stop to avoid infinite loop
        break

    if best is None:
        best = np.ones(50)
    return np.asarray(best, dtype=float)

