import numpy as np
import time


def _R_parts(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0 or not np.all(np.isfinite(h)):
        return -1.0, None, 0.0, 0.0
    c = np.convolve(h, h)
    L = np.empty(c.size + 2)
    L[0] = 0.0
    L[-1] = 0.0
    L[1:-1] = c
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    mx = L.max()
    if mx <= 0:
        return -1.0, L, s, mx
    return num / (s * s * mx), L, s, mx


def _R(h):
    return _R_parts(h)[0]


def _R_val_and_grad(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return -1.0, None
    n = h.size
    c = np.convolve(h, h)
    L = np.empty(c.size + 2)
    L[0] = 0.0; L[-1] = 0.0
    L[1:-1] = c
    a = L[:-1]; b = L[1:]
    A = a * a + a * b + b * b
    l2 = A.sum() / 3.0
    mx = L.max()
    if mx <= 0:
        return -1.0, None
    R = l2 / (s * s * mx)
    dA = np.empty_like(L)
    dA[:-1] += 2.0 * a + b
    dA[1:] += a + 2.0 * b
    dA /= 3.0
    gL = dA[1:-1] / (s * s * mx)
    c1 = np.convolve(gL, h[::-1])
    c2 = np.convolve(gL, h)
    g = c1[n - 1:2 * n - 1] + c2[n - 1:2 * n - 1]
    g += -2.0 * l2 / (s ** 3 * mx)
    return R, g


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    def tl():
        return time.process_time() < deadline

    rng = np.random.default_rng(918273 + int(budget_seconds * 7919))

    best = None
    bestR = -1.0

    def consider(h):
        nonlocal best, bestR
        h = np.asarray(h, dtype=float).ravel()
        if h.size == 0 or h.size > 50000:
            return False
        h = np.maximum(h, 0.0)
        if h.sum() <= 0:
            return False
        r = _R(h)
        if r > bestR:
            bestR = r
            best = h.copy()
            return True
        return False

    if start is not None:
        consider(start)

    def bb_grad(seed, dl, max_iter=100000):
        h = np.maximum(np.asarray(seed, dtype=float).copy(), 0.0)
        if h.sum() <= 0:
            return h, -1.0
        h /= h.sum()
        R, g = _R_val_and_grad(h)
        if g is None:
            return h, R
        g = g - g.mean()
        hprev = h.copy(); gprev = g.copy()
        step = 1e-3
        stall = 0
        it = 0
        while it < max_iter and time.process_time() < dl:
            it += 1
            dh = h - hprev
            dg = g - gprev
            denom = np.dot(dg, dg)
            if denom > 1e-30:
                step = max(1e-6, min(1.0, abs(np.dot(dh, dg)) / denom))
            improved = False
            for _ in range(25):
                if time.process_time() >= dl:
                    break
                trial = h - step * g
                np.maximum(trial, 0.0, out=trial)
                st = trial.sum()
                if st <= 0:
                    step *= 0.5
                    continue
                trial /= st
                rt = _R(trial)
                if rt > R + 1e-15:
                    hprev, gprev = h, g
                    h, R = trial, rt
                    R2, g = _R_val_and_grad(h)
                    g = g - g.mean()
                    step *= 1.5
                    improved = True
                    stall = 0
                    break
                step *= 0.5
            if not improved:
                stall += 1
                if stall >= 20:
                    break
        return h, R

    def coord_opt(seed, dl):
        h = np.maximum(np.asarray(seed, dtype=float).copy(), 0.0)
        s0 = h.sum()
        if s0 > 0:
            h /= s0
        cur = _R(h)
        n = h.size
        step = 0.05
        order = np.arange(n)
        stall = 0
        while time.process_time() < dl:
            improved = False
            rng.shuffle(order)
            for idx in order:
                if time.process_time() >= dl:
                    break
                old = h[idx]
                for d in (step, -step, step * 0.3, -step * 0.3, step * 0.1):
                    nv = old + d
                    if nv < 0:
                        nv = 0.0
                    if nv == old:
                        continue
                    h[idx] = nv
                    r = _R(h)
                    if r > cur:
                        cur = r
                        old = nv
                        improved = True
                    else:
                        h[idx] = old
            if not improved:
                stall += 1
                step *= 0.5
                if step < 1e-7 or stall >= 8:
                    break
        return h, cur

    def plateau(N, taper, power):
        x = np.linspace(-1, 1, N)
        t = np.clip((1 - np.abs(x)) / max(taper, 1e-6), 0, 1)
        return t ** power

    if best is None:
        for N in (150, 200, 230, 260, 300):
            for taper in (0.2, 0.4, 0.6, 0.8):
                for power in (0.5, 1.0, 1.5):
                    consider(plateau(N, taper, power))
            x = np.linspace(-1, 1, N)
            consider(np.exp(-3 * x**2))
            consider(np.ones(N))

    # Phase 1: main BB-gradient ascent from the given start
    if best is not None and tl():
        h, r = bb_grad(best, min(deadline, time.process_time() + budget_seconds * 0.40))
        if r > bestR:
            best, bestR = h, r

    # Phase 2: coordinate polish
    if best is not None and tl():
        h, r = coord_opt(best, min(deadline, time.process_time() + budget_seconds * 0.10))
        if r > bestR:
            best, bestR = h, r

    # Phase 3: alternating multiscale refinement with perturbation restarts
    tried = set()
    while tl() and best is not None:
        base = best.copy()
        N0 = base.size
        # multiscale resampling including a wider sweep of sizes
        sizes = [N0 - 30, N0 - 20, N0 - 10, N0 - 5, N0 - 2, N0 + 2, N0 + 5,
                 N0 + 10, N0 + 20, N0 + 30, N0 + 50,
                 200, 230, 260, 300, 330, 400]
        for M in sizes:
            if M < 20 or M > 50000 or M in tried:
                continue
            tried.add(M)
            if not tl():
                break
            xi = np.linspace(0, 1, N0)
            xo = np.linspace(0, 1, M)
            cand = np.interp(xo, xi, base)
            consider(cand)
            if tl():
                hb, rb = bb_grad(cand, min(deadline, time.process_time() + 2.5))
                if rb > bestR:
                    best, bestR = hb, rb
            if tl():
                hc, rc = coord_opt(cand, min(deadline, time.process_time() + 0.8))
                if rc > bestR:
                    best, bestR = hc, rc
        if not tl():
            break
        # perturbed restart at current size
        if tl() and best is not None:
            for scale in (0.02, 0.05):
                if not tl():
                    break
                jit = best * (1.0 + scale * rng.standard_normal(best.size))
                jit = np.maximum(jit, 0.0)
                if jit.sum() > 0:
                    if tl():
                        hj, rj = bb_grad(jit, min(deadline, time.process_time() + 1.5))
                        if rj > bestR:
                            best, bestR = hj, rj
        if not tl():
            break
        hb, rb = bb_grad(best, min(deadline, time.process_time() + 3.0))
        if rb > bestR:
            best, bestR = hb, rb
        if tl():
            hc, rc = coord_opt(best, min(deadline, time.process_time() + 1.2))
            if rc > bestR:
                best, bestR = hc, rc
        if not tl():
            break
        if len(tried) > 80:
            break

    # Phase 4: final polish
    if best is not None and tl():
        h, r = bb_grad(best, deadline)
        if r > bestR:
            best, bestR = h, r
    if best is not None and tl():
        h, r = coord_opt(best, deadline)
        if r > bestR:
            best, bestR = h, r

    if best is None:
        best = np.ones(50)
    return np.asarray(best, dtype=float)

