            cand = np.interp(xo, xi, base)
            consider(cand)
            if tl():
                hc = lbfgs_polish(cand, min(deadline, time.process_time() + 1.2), maxfun=250)
                if consider(hc):
                    gained = True
            if tl():
                hb, rb = bb_grad(cand, min(deadline, time.process_time() + 0.9))
                if rb > bestR:
                    best, bestR = hb, rb
                    gained = True
            if not tl():
                break
        if not tl():
            break
        # Perturb best a little and re-polish.
        if tl() and best is not None:
            jit = best * (1.0 + 0.03 * rng.standard_normal(best.size))
            jit = np.maximum(jit, 0.0)
            if jit.sum() > 0:
                hj = lbfgs_polish(jit, min(deadline, time.process_time() + 1.2), maxfun=300)
                if consider(hj):
                    gained = True
                if tl():
                    hb, rb = bb_grad(hj, min(deadline, time.process_time() + 0.8))
                    if rb > bestR:
                        best, bestR = hb, rb
                        gained = True
        if not tl():
