        if tl():
            hb, rb = bb_grad(best, min(deadline, time.process_time() + 1.2))
            if rb > bestR:
                best, bestR = hb, rb
                gained = True
        if not gained and len(tried) > 20:
            break

    # Final polish.
    if best is not None and tl():
        h = lbfgs_polish(best, deadline, maxfun=1000)
        consider(h)
    if best is not None and tl():
        h, r = bb_grad(best, deadline)
        if r > bestR:
            best, bestR = h, r
    if best is not None and tl():
        h, r = coord_opt(best, deadline)
        if r > bestR:
            best, bestR = h, r

    if best is None:
