        return None
    c = np.convolve(h, h)
    L = np.empty(c.size + 2)
    L[0] = 0.0
    L[-1] = 0.0
    L[1:-1] = c
    a = L[:-1]
    b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    mx = L.max()
    if mx <= 0:
