from scipy.optimize import minimize


def _parts(h):
    h = np.asarray(h, dtype=float)
    if h.size == 0 or not np.all(np.isfinite(h)):
        return None
    s = h.sum()
    if s <= 0:
        return None
    c = np.convolve(h, h)
    L = np.empty(c.size + 2)
    L[0] = 0.0
    L[-1] = 0.0
    L[1:-1] = c
    a = L[:-1]
    b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    mx = L.max()
    if mx <= 0:
        return None
    return num / (s * s * mx), L, s, mx, num


def _R(h):
    p = _parts(h)
    return -1.0 if p is None else p[0]


def _grad(h, L, s, mx, num):
    n = h.size
    a = L[:-1]
    b = L[1:]
    dL = np.zeros_like(L)
    dL[:-1] += (2.0 * a + b) / 3.0
    dL[1:] += (a + 2.0 * b) / 3.0
    gL = dL[1:-1]
    c1 = np.convolve(gL, h[::-1])
    c2 = np.convolve(gL, h)
    dnum = c1[n - 1:2 * n - 1] + c2[n - 1:2 * n - 1]
    argmax = int(np.argmax(L))
    dmx = np.zeros(n)
    if 1 <= argmax <= 2 * n - 1:
        k = argmax - 1
        lo = max(0, k - n + 1)
        hi = min(n, k + 1)
        idx = np.arange(lo, hi)
        dmx[idx] = 2.0 * h[k - idx]
    s2mx = s * s * mx
    return (dnum * s2mx - num * (2.0 * s * mx + s * s * dmx)) / (s2mx * s2mx)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    def tl():
        return time.process_time() < deadline

    rng = np.random.default_rng(20251 + int(budget_seconds * 911))

    best = None
    bestR = -1.0

    def consider(h):
        nonlocal best, bestR
        h = np.asarray(h, dtype=float).ravel()
        if h.size == 0 or h.size > 50000:
            return False
        h = np.maximum(h, 0.0)
        if h.sum() <= 0:
            return False
        r = _R(h)
        if r > bestR:
            bestR = r
            best = h.copy()
            return True
        return False

    if start is not None:
        consider(start)

    def lbfgs_polish(seed, dl, maxfun=400, eps=1e-9):
        h = np.maximum(np.asarray(seed, dtype=float).copy(), 0.0)
        if h.sum() <= 0:
            return h
        base_scale = h.max()
        if base_scale <= 0:
            return h
        z0 = np.log(np.maximum(h / base_scale, eps))

        def negR_grad(z):
            if time.process_time() >= dl:
                raise TimeoutError
            hh = np.exp(z) * base_scale
            p = _parts(hh)
            if p is None:
                return 1e10, z * 0.0
            r, L, s, mx, num = p
            g = _grad(hh, L, s, mx, num)
            return -r, -g * hh

        try:
            res = minimize(negR_grad, z0, jac=True, method="L-BFGS-B",
                           options={"maxiter": maxfun, "maxfun": maxfun,
                                    "ftol": 1e-16, "gtol": 1e-13})
            cand = np.exp(res.x) * base_scale
            if np.all(np.isfinite(cand)) and cand.sum() > 0:
                if _R(cand) > _R(h):
                    return cand
        except Exception:
            pass
        return h

    def bb_grad(seed, dl, max_iter=200000):
        h = np.maximum(np.asarray(seed, dtype=float).copy(), 0.0)
        if h.sum() <= 0:
            return h, -1.0
        h /= h.sum()
        p = _parts(h)
        if p is None:
            return h, -1.0
        R, L, s, mx, num = p
        g = _grad(h, L, s, mx, num)
        g = g - g.mean()
        hprev = h.copy(); gprev = g.copy()
        step = 1e-3
        stall = 0
        it = 0
        while it < max_iter and time.process_time() < dl:
            it += 1
            dh = h - hprev
            dg = g - gprev
            denom = float(np.dot(dg, dg))
            if denom > 1e-30:
                step = max(1e-8, min(1.0, abs(float(np.dot(dh, dg))) / denom))
            improved = False
            for _ in range(30):
                if time.process_time() >= dl:
                    break
                trial = h - step * g
                np.maximum(trial, 0.0, out=trial)
                st = trial.sum()
                if st <= 0:
                    step *= 0.5
                    continue
                trial /= st
                rt = _R(trial)
                if rt > R + 1e-16:
                    hprev, gprev = h, g
                    h, R = trial, rt
                    p = _parts(h)
                    if p is None:
                        break
                    R, L, s, mx, num = p
                    g = _grad(h, L, s, mx, num)
                    g = g - g.mean()
                    step *= 1.5
                    improved = True
                    stall = 0
                    break
                step *= 0.5
            if not improved:
                stall += 1
                if stall >= 25:
                    break
        return h, R

    def coord_opt(seed, dl):
        h = np.maximum(np.asarray(seed, dtype=float).copy(), 0.0)
        s0 = h.sum()
        if s0 > 0:
            h /= s0
        cur = _R(h)
        n = h.size
        step = 0.05
        order = np.arange(n)
        stall = 0
        while time.process_time() < dl:
            improved = False
            rng.shuffle(order)
            for idx in order:
                if time.process_time() >= dl:
                    break
                old = h[idx]
                for d in (step, -step, step * 0.3, -step * 0.3, step * 0.1):
                    nv = old + d
                    if nv < 0:
                        nv = 0.0
                    if nv == old:
                        continue
                    h[idx] = nv
                    r = _R(h)
                    if r > cur:
                        cur = r
                        old = nv
                        improved = True
                    else:
                        h[idx] = old
            if not improved:
                stall += 1
                step *= 0.5
                if step < 1e-8 or stall >= 8:
                    break
        return h, cur

    def plateau(N, taper, power):
        x = np.linspace(-1, 1, N)
        t = np.clip((1 - np.abs(x)) / max(taper, 1e-6), 0, 1)
        return t ** power

    if best is None:
        for N in (150, 200, 230, 260, 300):
            for taper in (0.2, 0.4, 0.6, 0.8):
                for power in (0.5, 1.0, 1.5):
                    consider(plateau(N, taper, power))
            x = np.linspace(-1, 1, N)
            consider(np.exp(-3 * x ** 2))
            consider(np.ones(N))

    if best is not None and tl():
        h = lbfgs_polish(best, min(deadline, time.process_time() + budget_seconds * 0.18), maxfun=500)
        consider(h)

    if best is not None and tl():
        h, r = bb_grad(best, min(deadline, time.process_time() + budget_seconds * 0.14))
        if r > bestR:
            best, bestR = h, r
    if best is not None and tl():
        h, r = coord_opt(best, min(deadline, time.process_time() + budget_seconds * 0.05))
        if r > bestR:
            best, bestR = h, r

    # Phase C: resample/refine loop with fine-grained N search around best.
    tried = set()
    while tl() and best is not None:
        base = best.copy()
        N0 = base.size
        gained = False
        sizes = [N0 - 1, N0 + 1, N0 - 2, N0 + 2, N0 - 4, N0 + 4, N0 - 8, N0 + 8,
                 N0 - 15, N0 + 15, N0 - 30, N0 + 30]
        for M in sizes:
            if M < 20 or M > 50000 or M in tried:
                continue
            tried.add(M)
            if not tl():
                break
            xi = np.linspace(0, 1, N0)
            xo = np.linspace(0, 1, M)
            cand = np.interp(xo, xi, base)
            consider(cand)
            if tl():
                hc = lbfgs_polish(cand, min(deadline, time.process_time() + 1.2), maxfun=200)
                if consider(hc):
                    gained = True
            if tl():
                hb, rb = bb_grad(cand, min(deadline, time.process_time() + 1.0))
                if rb > bestR:
                    best, bestR = hb, rb
                    gained = True
        if not tl():
            break
        if tl():
            h = lbfgs_polish(best, min(deadline, time.process_time() + 1.5), maxfun=300)
            consider(h)
        if tl():
            hb, rb = bb_grad(best, min(deadline, time.process_time() + 1.2))
            if rb > bestR:
                best, bestR = hb, rb
                gained = True
        if tl():
            hc, rc = coord_opt(best, min(deadline, time.process_time() + 0.5))
            if rc > bestR:
                best, bestR = hc, rc
                gained = True
        if not gained:
            if tl():
                pert = best.copy()
                noise = rng.normal(0.0, 0.01, pert.size)
                pert = np.maximum(pert * (1.0 + noise), 0.0)
                if pert.sum() > 0:
                    consider(pert)
                    hp = lbfgs_polish(pert, min(deadline, time.process_time() + 1.0), maxfun=250)
                    consider(hp)
            if not gained and len(tried) > 40:
                M = int(rng.integers(max(20, N0 - 60), min(50000, N0 + 60)))
                if M not in tried and M >= 20:
                    tried.add(M)
                    xi = np.linspace(0, 1, N0)
                    xo = np.linspace(0, 1, M)
                    cand = np.interp(xo, xi, best)
                    consider(cand)
                    if tl():
                        h = lbfgs_polish(cand, min(deadline, time.process_time() + 1.0), maxfun=200)
                        consider(h)

    # Phase D: fine integer-N scan around the best size, then polish.
    if best is not None and tl():
        N0 = best.size
        for M in range(max(20, N0 - 12), min(50000, N0 + 12) + 1):
            if not tl():
                break
            xi = np.linspace(0, 1, N0)
            xo = np.linspace(0, 1, M)
            cand = np.interp(xo, xi, best)
            if tl():
                hc = lbfgs_polish(cand, min(deadline, time.process_time() + 0.9), maxfun=180)
                consider(hc)

    if best is not None and tl():
        h = lbfgs_polish(best, min(deadline, time.process_time() + budget_seconds * 0.10), maxfun=500)
        consider(h)
    if best is not None and tl():
        h, r = bb_grad(best, deadline)
        if r > bestR:
            best, bestR = h, r
    if best is not None and tl():
        h, r = coord_opt(best, deadline)
        if r > bestR:
            best, bestR = h, r

    if best is None:
        best = np.ones(50)
    return np.asarray(best, dtype=float)

