    if start is not None:
        consider(start)

    def lbfgs_polish(seed, dl, maxfun=500):
        h = np.maximum(np.asarray(seed, dtype=float).copy(), 0.0)
        if h.sum() <= 0:
            return h
        base_scale = h.max()
        if base_scale <= 0:
            return h
