        cur = _R(h)
        n = h.size
        step = 0.05
        order = np.arange(n)
        stall = 0
        while time.process_time() < dl:
            improved = False
            rng.shuffle(order)
            for idx in order:
                if time.process_time() >= dl:
                    break
                old = h[idx]
                for d in (step, -step, step * 0.3, -step * 0.3, step * 0.1):
                    nv = old + d
                    if nv < 0:
                        nv = 0.0
                    if nv == old:
                        continue
                    h[idx] = nv
                    r = _R(h)
                    if r > cur:
                        cur = r
                        old = nv
                        improved = True
                    else:
                        h[idx] = old
            if not improved:
                stall += 1
                step *= 0.5
                if step < 1e-8 or stall >= 8:
                    break
        return h, cur

    def plateau(N, taper, power):
        x = np.linspace(-1, 1, N)
        t = np.clip((1 - np.abs(x)) / max(taper, 1e-6), 0, 1)
        return t ** power

    if best is None:
        for N in (150, 200, 230, 260, 300):
            for taper in (0.2, 0.4, 0.6, 0.8):
                for power in (0.5, 1.0, 1.5):
