    if best is not None and tl():
        h = lbfgs_polish(best, min(deadline, time.process_time() + budget_seconds * 0.18), maxfun=500)
        consider(h)

    # Phase B: BB gradient
    if best is not None and tl():
        h, r = bb_grad(best, min(deadline, time.process_time() + budget_seconds * 0.12))
        if r > bestR:
            best, bestR = h, r
    if best is not None and tl():
        h, r = coord_opt(best, min(deadline, time.process_time() + budget_seconds * 0.05))
        if r > bestR:
            best, bestR = h, r

    # Phase C: resample + L-BFGS refinement loop.
    # Key change: also try *non-uniform* resampling (shifted knots), and use
    # larger N jumps to escape the N~298 basin. Each candidate gets a
    # multi-restart L-BFGS (a few perturbed seeds) so we escape nearby flats.
    tried = {}
    while tl() and best is not None:
        base = best.copy()
        N0 = base.size
        gained = False
        sizes = [N0 - 1, N0 + 1, N0 - 2, N0 + 2, N0 - 3, N0 + 3, N0 - 4, N0 + 4,
                 N0 - 6, N0 + 6, N0 - 8, N0 + 8, N0 - 12, N0 + 12,
                 N0 - 20, N0 + 20, N0 - 35, N0 + 35]
        for M in sizes:
            if M < 20 or M > 50000:
                continue
            cnt = tried.get(M, 0)
            if cnt >= 2:
                continue
            tried[M] = cnt + 1
            if not tl():
                break
            xi = np.linspace(0, 1, N0)
            xo = np.linspace(0, 1, M)
            cand = np.interp(xo, xi, base)
            # Multi-restart L-BFGS: try the plain resample plus a couple of
            # small multiplicative perturbations, keep the best.
            seeds = [cand]
            for sigma in (0.01, 0.03):
                seeds.append(np.maximum(cand * (1.0 + sigma * rng.standard_normal(M)), 0.0))
            for s in seeds:
                if not tl():
                    break
                hc = lbfgs_polish(s, min(deadline, time.process_time() + 0.9), maxfun=220)
                if consider(hc):
                    gained = True
            if tl():
                hb, rb = bb_grad(cand, min(deadline, time.process_time() + 0.6))
                if rb > bestR:
                    best, bestR = hb, rb
                    gained = True
        if not tl():
            break
        # Polish current best
        if tl():
            hc = lbfgs_polish(best, min(deadline, time.process_time() + 1.2), maxfun=300)
            if consider(hc):
                gained = True
        # Perturbation escape (larger sigma range)
        if tl() and not gained:
            for sigma in (0.005, 0.02, 0.05, 0.1):
                if not tl():
                    break
                jit = best * (1.0 + sigma * rng.standard_normal(best.size))
                jit = np.maximum(jit, 0.0)
                if jit.sum() > 0:
                    hj = lbfgs_polish(jit, min(deadline, time.process_time() + 1.0), maxfun=200)
                    if consider(hj):
                        gained = True
                        break
        if not gained and len(tried) > 60:
            break

    # Phase D: final polish
    if best is not None and tl():
        hc = lbfgs_polish(best, min(deadline, time.process_time() + 1.5), maxfun=400)
        consider(hc)
    if best is not None and tl():
        h, r = bb_grad(best, deadline)
        if r > bestR:
            best, bestR = h, r
    if best is not None and tl():
        h, r = coord_opt(best, deadline)
        if r > bestR:
            best, bestR = h, r

    if best is None:
        best = np.ones(50)
    return np.asarray(best, dtype=float)

