                    p = _parts(h)
                    if p is None:
                        break
                    R, L, s, mx, num = p
                    g = _grad(h, L, s, mx, num)
                    g = g - g.mean()
                    step *= 1.5
                    improved = True
                    stall = 0
                    break
                step *= 0.5
            if not improved:
                stall += 1
                if stall >= 25:
                    break
        return h, R

    def coord_opt(seed, dl):
        h = np.maximum(np.asarray(seed, dtype=float).copy(), 0.0)
        s0 = h.sum()
        if s0 > 0:
            h /= s0
        cur = _R(h)
        n = h.size
        scale = max(h.max(), 1e-9)
        step = 0.05 * scale
        order = np.arange(n)
        stall = 0
        while time.process_time() < dl:
            improved = False
            rng.shuffle(order)
            for idx in order:
                if time.process_time() >= dl:
                    break
                old = h[idx]
                for d in (step, -step, step * 0.3, -step * 0.3, step * 0.1):
                    nv = old + d
                    if nv < 0:
                        nv = 0.0
                    if nv == old:
                        continue
                    h[idx] = nv
                    r = _R(h)
                    if r > cur:
                        cur = r
                        old = nv
                        improved = True
                    else:
                        h[idx] = old
            if not improved:
                stall += 1
                step *= 0.5
                if step < 1e-9 * scale or stall >= 8:
                    break
        return h, cur

    def plateau(N, taper, power):
        x = np.linspace(-1, 1, N)
        t = np.clip((1 - np.abs(x)) / max(taper, 1e-6), 0, 1)
        return t ** power

    if best is None:
        for N in (150, 200, 230, 260, 300):
            for taper in (0.2, 0.4, 0.6, 0.8):
                for power in (0.5, 1.0, 1.5):
                    consider(plateau(N, taper, power))
            x = np.linspace(-1, 1, N)
            consider(np.exp(-3 * x ** 2))
            consider(np.ones(N))

