    if best is not None and tl():
        h = lbfgs_polish(best, min(deadline, time.process_time() + budget_seconds * 0.18), maxfun=500)
        consider(h)

    # Phase B: BB gradient + coord
    if best is not None and tl():
        h, r = bb_grad(best, min(deadline, time.process_time() + budget_seconds * 0.10))
        if r > bestR:
            best, bestR = h, r
    if best is not None and tl():
        h, r = coord_opt(best, min(deadline, time.process_time() + budget_seconds * 0.04))
        if r > bestR:
            best, bestR = h, r

    # Phase C: alternating resample/refine. Mass-conserving (area-preserving)
    # resampling creates better seeds than plain linear interp; also try
    # spectral (DCT-based) resampling for smooth plateau structure.
    def resample_area(base, M):
        N0 = base.size
        # treat heights as samples; integrate to cumulative mass
        csum = np.concatenate(([0.0], np.cumsum(base)))
        total = csum[-1]
        if total <= 0:
            return np.interp(np.linspace(0, 1, M), np.linspace(0, 1, N0), base)
        # edges of new bins in original-index space
        edges = np.linspace(0.0, N0, M + 1)
        dens = np.zeros(M)
        for i in range(M):
            a, b = edges[i], edges[i + 1]
            ia = int(np.floor(a)); ib = int(np.floor(b))
            if ia == ib:
                dens[i] = base[min(ia, N0 - 1)]
            else:
                # integrate piecewise-constant (nearest sample) approx
                acc = 0.0
                acc += (min(1.0, a - ia if a > ia else 1.0)) * 0.0
                # simple: weighted average over covered indices using cumsum
                lo = a; hi = b
                # use trapezoid on cumulative
                def cum_at(x):
                    k = int(np.floor(x))
                    if k >= N0:
                        return csum[-1]
                    if k < 0:
                        return 0.0
                    frac = x - k
                    return csum[k] + frac * (base[k] if k < N0 else 0.0)
                acc = cum_at(hi) - cum_at(lo)
                dens[i] = acc / (b - a) if b > a else 0.0
        return dens

    def resample_dct(base, M):
        N0 = base.size
        if M == N0:
            return base.copy()
        try:
            coef = np.fft.rfft(base)
            # pad/truncate spectrum
            L = min(len(coef), M // 2 + 1)
            new = np.zeros(M // 2 + 1, dtype=complex)
            new[:L] = coef[:L]
            out = np.fft.irfft(new, n=M)
            # smooth edges
            w = np.hanning(M)
            out = out * (0.6 + 0.4 * w)
            out = np.maximum(out, 0.0)
            return out
        except Exception:
            return np.interp(np.linspace(0, 1, M), np.linspace(0, 1, N0), base)

    tried = {}
    while tl() and best is not None:
        base = best.copy()
        N0 = base.size
        gained = False
        sizes = [N0 - 1, N0 + 1, N0 - 2, N0 + 2, N0 - 3, N0 + 3, N0 - 4, N0 + 4,
                 N0 - 6, N0 + 6, N0 - 8, N0 + 8, N0 - 12, N0 + 12,
                 N0 - 20, N0 + 20, N0 - 35, N0 + 35]
        for M in sizes:
            if M < 20 or M > 50000:
                continue
            cnt = tried.get(M, 0)
            if cnt >= 2:
                continue
            tried[M] = cnt + 1
            if not tl():
                break
            xi = np.linspace(0, 1, N0)
            xo = np.linspace(0, 1, M)
            cand_lin = np.interp(xo, xi, base)
            cand_area = resample_area(base, M)
            cand_dct = resample_dct(base, M)
            seeds = [cand_lin, cand_area, cand_dct]
            for sigma in (0.01, 0.03):
                seeds.append(np.maximum(cand_area * (1.0 + sigma * rng.standard_normal(M)), 0.0))
            for s in seeds:
                if not tl():
                    break
                hc = lbfgs_polish(s, min(deadline, time.process_time() + 0.9), maxfun=220)
                if consider(hc):
                    gained = True
            if tl():
                hb, rb = bb_grad(cand_area, min(deadline, time.process_time() + 0.6))
                if rb > bestR:
                    best, bestR = hb, rb
                    gained = True
        if not tl():
            break
        if tl():
            hc = lbfgs_polish(best, min(deadline, time.process_time() + 1.2), maxfun=300)
            if consider(hc):
                gained = True
        if tl() and not gained:
            for sigma in (0.005, 0.02, 0.05, 0.1):
                if not tl():
                    break
                jit = best * (1.0 + sigma * rng.standard_normal(best.size))
                jit = np.maximum(jit, 0.0)
                if jit.sum() > 0:
                    hj = lbfgs_polish(jit, min(deadline, time.process_time() + 1.0), maxfun=200)
                    if consider(hj):
                        gained = True
                        break
        if not gained and len(tried) > 60:
            break

    # Phase D: final polish
    if best is not None and tl():
        hc = lbfgs_polish(best, min(deadline, time.process_time() + 1.5), maxfun=400)
        consider(hc)
    if best is not None and tl():
        h, r = bb_grad(best, deadline)
        if r > bestR:
            best, bestR = h, r
    if best is not None and tl():
        h, r = coord_opt(best, deadline)
        if r > bestR:
            best, bestR = h, r

    if best is None:
        best = np.ones(50)
    return np.asarray(best, dtype=float)

import numpy as np
import time
from scipy.optimize import minimize


def _parts(h):
    h = np.asarray(h, dtype=float)
    if h.size == 0 or not np.all(np.isfinite(h)):
        return None
    s = h.sum()
    if s <= 0:
        return None
    c = np.convolve(h, h)
    L = np.empty(c.size + 2)
    L[0] = 0.0
    L[-1] = 0.0
    L[1:-1] = c
    a = L[:-1]
    b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    mx = L.max()
    if mx <= 0:
        return None
    return num / (s * s * mx), L, s, mx, num


def _R(h):
    p = _parts(h)
    return -1.0 if p is None else p[0]


def _grad(h, L, s, mx, num):
    n = h.size
    a = L[:-1]
    b = L[1:]
    dL = np.zeros_like(L)
    dL[:-1] += (2.0 * a + b) / 3.0
    dL[1:] += (a + 2.0 * b) / 3.0
    gL = dL[1:-1]
    c1 = np.convolve(gL, h[::-1])
    c2 = np.convolve(gL, h)
    dnum = c1[n - 1:2 * n - 1] + c2[n - 1:2 * n - 1]
    argmax = int(np.argmax(L))
    dmx = np.zeros(n)
    if 1 <= argmax <= 2 * n - 1:
        k = argmax - 1
        lo = max(0, k - n + 1)
        hi = min(n, k + 1)
        idx = np.arange(lo, hi)
        dmx[idx] = 2.0 * h[k - idx]
    s2mx = s * s * mx
    return (dnum * s2mx - num * (2.0 * s * mx + s * s * dmx)) / (s2mx * s2mx)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    def tl():
        return time.process_time() < deadline

    rng = np.random.default_rng(314159 + int(budget_seconds * 1000))

    best = None
    bestR = -1.0

    def consider(h):
        nonlocal best, bestR
        h = np.asarray(h, dtype=float).ravel()
        if h.size == 0 or h.size > 50000:
            return False
        h = np.maximum(h, 0.0)
        if h.sum() <= 0:
            return False
        r = _R(h)
        if r > bestR:
            bestR = r
            best = h.copy()
            return True
        return False

    if start is not None:
        consider(start)

    def lbfgs_polish(seed, dl, maxfun=800):
        h = np.maximum(np.asarray(seed, dtype=float).copy(), 0.0)
        if h.sum() <= 0:
            return h
        base_scale = h.max()
        if base_scale <= 0:
            return h
        z0 = np.log(np.maximum(h / base_scale, 1e-9))

        def negR_grad(z):
            if time.process_time() >= dl:
                raise TimeoutError
            hh = np.exp(z) * base_scale
            p = _parts(hh)
            if p is None:
                return 1e10, z * 0.0
            r, L, s, mx, num = p
            g = _grad(hh, L, s, mx, num)
            return -r, -g * hh

        try:
            res = minimize(negR_grad, z0, jac=True, method="L-BFGS-B",
                           options={"maxiter": maxfun, "maxfun": maxfun,
                                    "ftol": 1e-18, "gtol": 1e-14})
            cand = np.exp(res.x) * base_scale
            if np.all(np.isfinite(cand)) and cand.sum() > 0:
                if _R(cand) > _R(h):
                    return cand
        except Exception:
            pass
        return h

    def bb_grad(seed, dl, max_iter=200000):
        h = np.maximum(np.asarray(seed, dtype=float).copy(), 0.0)
        if h.sum() <= 0:
            return h, -1.0
        h /= h.sum()
        p = _parts(h)
        if p is None:
            return h, -1.0
        R, L, s, mx, num = p
        g = _grad(h, L, s, mx, num)
        g = g - g.mean()
        hprev = h.copy(); gprev = g.copy()
        step = 1e-3
        stall = 0
        it = 0
        while it < max_iter and time.process_time() < dl:
            it += 1
            dh = h - hprev
            dg = g - gprev
            denom = float(np.dot(dg, dg))
            if denom > 1e-30:
                step = max(1e-9, min(1.0, abs(float(np.dot(dh, dg))) / denom))
            improved = False
            for _ in range(30):
                if time.process_time() >= dl:
                    break
                trial = h - step * g
                np.maximum(trial, 0.0, out=trial)
                st = trial.sum()
                if st <= 0:
                    step *= 0.5
                    continue
                trial /= st
                rt = _R(trial)
                if rt > R + 1e-16:
                    hprev, gprev = h, g
                    h, R = trial, rt
                    p = _parts(h)
                    if p is None:
                        break
                    R, L, s, mx, num = p
                    g = _grad(h, L, s, mx, num)
                    g = g - g.mean()
                    step *= 1.5
                    improved = True
                    stall = 0
                    break
                step *= 0.5
            if not improved:
                stall += 1
                if stall >= 25:
                    break
        return h, R

    def coord_opt(seed, dl):
        h = np.maximum(np.asarray(seed, dtype=float).copy(), 0.0)
        s0 = h.sum()
        if s0 > 0:
            h /= s0
        cur = _R(h)
        n = h.size
        step = 0.05
        order = np.arange(n)
        stall = 0
        while time.process_time() < dl:
            improved = False
            rng.shuffle(order)
            for idx in order:
                if time.process_time() >= dl:
                    break
                old = h[idx]
                for d in (step, -step, step * 0.3, -step * 0.3, step * 0.1):
                    nv = old + d
                    if nv < 0:
                        nv = 0.0
                    if nv == old:
                        continue
                    h[idx] = nv
                    r = _R(h)
                    if r > cur:
                        cur = r
                        old = nv
                        improved = True
                    else:
                        h[idx] = old
            if not improved:
                stall += 1
                step *= 0.5
                if step < 1e-8 or stall >= 8:
                    break
        return h, cur

    def plateau(N, taper, power):
        x = np.linspace(-1, 1, N)
        t = np.clip((1 - np.abs(x)) / max(taper, 1e-6), 0, 1)
        return t ** power

    def resample_dct(base, M):
        N0 = base.size
        if N0 == M:
            return base.copy()
        # DCT-based resampling preserving smooth structure
        try:
            d = np.fft.rfft(base)
        except Exception:
            xi = np.linspace(0, 1, N0)
            xo = np.linspace(0, 1, M)
            return np.interp(xo, xi, base)
        # Pad/truncate spectrum
        if M <= N0:
            d2 = d[: (M // 2 + 1)]
        else:
            d2 = np.zeros(M // 2 + 1, dtype=complex)
            d2[: d.size] = d
        out = np.fft.irfft(d2, n=M)
        return np.maximum(out, 0.0)

    if best is None:
        for N in (150, 200, 230, 260, 300):
            for taper in (0.2, 0.4, 0.6, 0.8):
                for power in (0.5, 1.0, 1.5):
                    consider(plateau(N, taper, power))
            x = np.linspace(-1, 1, N)
            consider(np.exp(-3 * x ** 2))
            consider(np.ones(N))

    # Phase A: L-BFGS polish on start
    if best is not None and tl():
        h = lbfgs_polish(best, min(deadline, time.process_time() + budget_seconds * 0.20), maxfun=800)
        consider(h)

    # Phase B: BB gradient
    if best is not None and tl():
        h, r = bb_grad(best, min(deadline, time.process_time() + budget_seconds * 0.12))
        if r > bestR:
            best, bestR = h, r
    if best is not None and tl():
        h, r = coord_opt(best, min(deadline, time.process_time() + budget_seconds * 0.05))
        if r > bestR:
            best, bestR = h, r

    # Phase C: resample + L-BFGS refinement loop, DCT and linear resampling
    tried = {}
    while tl() and best is not None:
        base = best.copy()
        N0 = base.size
        gained = False
        sizes = [N0 - 1, N0 + 1, N0 - 2, N0 + 2, N0 - 3, N0 + 3, N0 - 4, N0 + 4,
                 N0 - 6, N0 + 6, N0 - 8, N0 + 8, N0 - 12, N0 + 12,
                 N0 - 20, N0 + 20, N0 - 35, N0 + 35]
        for M in sizes:
            if M < 20 or M > 50000:
                continue
            cnt = tried.get(M, 0)
            if cnt >= 2:
                continue
            tried[M] = cnt + 1
            if not tl():
                break
            for use_dct in (True, False):
                if not tl():
                    break
                if use_dct:
                    cand = resample_dct(base, M)
                else:
                    xi = np.linspace(0, 1, N0)
                    xo = np.linspace(0, 1, M)
                    cand = np.interp(xo, xi, base)
                if consider(cand):
                    gained = True
                # Polish this candidate quickly
                if tl():
                    h = lbfgs_polish(cand, min(deadline, time.process_time() + 1.5), maxfun=200)
                    if consider(h):
                        gained = True
        if not tl():
            break
        # Full polish on best
        h = lbfgs_polish(best, min(deadline, time.process_time() + 2.5), maxfun=400)
        if consider(h):
            gained = True
        h, r = bb_grad(best, min(deadline, time.process_time() + 1.5))
        if r > bestR:
            best, bestR = h, r
            gained = True
        if not gained and len(tried) > 30:
            break

    # Phase D: final polish with remaining time
    if best is not None and tl():
        h = lbfgs_polish(best, deadline, maxfun=2000)
        consider(h)
    if best is not None and tl():
        h, r = bb_grad(best, deadline)
        if r > bestR:
            best, bestR = h, r

    if best is None:
        best = np.ones(50)
    return np.asarray(best, dtype=float)

