import numpy as np
import time
from scipy.optimize import minimize


def _parts(h):
    h = np.asarray(h, dtype=float)
    if h.size == 0 or not np.all(np.isfinite(h)):
        return None
    s = h.sum()
    if s <= 0:
        return None
    c = np.convolve(h, h)
    L = np.empty(c.size + 2)
    L[0] = 0.0
    L[-1] = 0.0
    L[1:-1] = c
    a = L[:-1]
    b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    mx = L.max()
    if mx <= 0:
        return None
    return num / (s * s * mx), L, s, mx, num


def _R(h):
    p = _parts(h)
    return -1.0 if p is None else p[0]


def _grad(h, L, s, mx, num):
    n = h.size
    a = L[:-1]
    b = L[1:]
    dL = np.zeros_like(L)
    dL[:-1] += (2.0 * a + b) / 3.0
    dL[1:] += (a + 2.0 * b) / 3.0
    gL = dL[1:-1]
    c1 = np.convolve(gL, h[::-1])
    c2 = np.convolve(gL, h)
    dnum = c1[n - 1:2 * n - 1] + c2[n - 1:2 * n - 1]
    argmax = int(np.argmax(L))
    dmx = np.zeros(n)
    if 1 <= argmax <= 2 * n - 1:
        k = argmax - 1
        lo = max(0, k - n + 1)
        hi = min(n, k + 1)
        idx = np.arange(lo, hi)
        dmx[idx] = 2.0 * h[k - idx]
    s2mx = s * s * mx
    return (dnum * s2mx - num * (2.0 * s * mx + s * s * dmx)) / (s2mx * s2mx)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    def tl():
        return time.process_time() < deadline

    rng = np.random.default_rng(20240501 + int(budget_seconds * 5003))

    best = None
    bestR = -1.0

    def consider(h):
        nonlocal best, bestR
        h = np.asarray(h, dtype=float).ravel()
        if h.size == 0 or h.size > 50000:
            return False
        h = np.maximum(h, 0.0)
        if h.sum() <= 0:
            return False
        r = _R(h)
        if r > bestR:
            bestR = r
            best = h.copy()
            return True
        return False

    if start is not None:
        consider(start)

    def lbfgs_polish(seed, dl, maxfun=300):
        h = np.maximum(np.asarray(seed, dtype=float).copy(), 0.0)
        if h.sum() <= 0:
            return h
        base_scale = h.max()
        if base_scale <= 0:
            return h
        z0 = np.log(np.maximum(h / base_scale, 1e-10))

        def negR_grad(z):
            if time.process_time() >= dl:
                raise TimeoutError
            hh = np.exp(z) * base_scale
            p = _parts(hh)
            if p is None:
                return 1e10, z * 0.0
            r, L, s, mx, num = p
            g = _grad(hh, L, s, mx, num)
            return -r, -g * hh

        try:
            res = minimize(negR_grad, z0, jac=True, method="L-BFGS-B",
                           options={"maxiter": maxfun, "maxfun": maxfun,
                                    "ftol": 1e-17, "gtol": 1e-14})
            cand = np.exp(res.x) * base_scale
            if np.all(np.isfinite(cand)) and cand.sum() > 0:
                if _R(cand) > _R(h):
                    return cand
        except Exception:
            pass
        return h

    def bb_grad(seed, dl, max_iter=200000):
        h = np.maximum(np.asarray(seed, dtype=float).copy(), 0.0)
        if h.sum() <= 0:
            return h, -1.0
        h /= h.sum()
