        consider(start)

    def symmetrize(h):
        h = np.asarray(h, dtype=float)
        n = h.size
        if n < 3:
            return h
        return 0.5 * (h + h[::-1])

    def lbfgs_polish(seed, dl, maxfun=400):
        h = np.maximum(np.asarray(seed, dtype=float).copy(), 0.0)
        if h.sum() <= 0:
            return h
        base_scale = h.max()
