                           options={"maxiter": maxfun, "maxfun": maxfun,
                                    "ftol": 1e-18, "gtol": 1e-15})
            cand = np.exp(res.x) * base_scale
            if np.all(np.isfinite(cand)) and cand.sum() > 0:
                if _R(cand) > _R(h):
                    return cand
        except Exception:
            pass
        return h

    def bb_grad(seed, dl, max_iter=200000):
        h = np.maximum(np.asarray(seed, dtype=float).copy(), 0.0)
        if h.sum() <= 0:
            return h, -1.0
        h /= h.sum()
        p = _parts(h)
        if p is None:
            return h, -1.0
        R, L, s, mx, num = p
        g = _grad(h, L, s, mx, num)
        g = g - g.mean()
        hprev = h.copy(); gprev = g.copy()
        step = 1e-3
        stall = 0
        it = 0
        while it < max_iter and time.process_time() < dl:
            it += 1
            dh = h - hprev
            dg = g - gprev
            denom = float(np.dot(dg, dg))
            if denom > 1e-30:
                step = max(1e-10, min(1.0, abs(float(np.dot(dh, dg))) / denom))
            improved = False
            for _ in range(40):
                if time.process_time() >= dl:
                    break
                trial = h - step * g
                np.maximum(trial, 0.0, out=trial)
                st = trial.sum()
                if st <= 0:
                    step *= 0.5
                    continue
                trial /= st
                rt = _R(trial)
                if rt > R + 1e-17:
                    hprev, gprev = h, g
                    h, R = trial, rt
                    p = _parts(h)
                    if p is None:
                        break
                    R, L, s, mx, num = p
                    g = _grad(h, L, s, mx, num)
                    g = g - g.mean()
                    step *= 1.5
                    improved = True
                    stall = 0
                    break
                step *= 0.5
            if not improved:
                stall += 1
                if stall >= 30:
                    break
        return h, R

    if state["best"] is None:
        for N in (200, 260, 300, 337):
            for taper in (0.3, 0.5, 0.7):
                for power in (0.5, 1.0, 1.5):
                    x = np.linspace(-1, 1, N)
                    t = np.clip((1 - np.abs(x)) / taper, 0, 1)
                    consider(t ** power)

