import numpy as np
import time
from scipy.optimize import minimize


def _parts(h):
    h = np.asarray(h, dtype=float)
    if h.size == 0 or not np.all(np.isfinite(h)):
        return None
    s = h.sum()
    if s <= 0:
        return None
    c = np.convolve(h, h)
    L = np.empty(c.size + 2)
    L[0] = 0.0
    L[-1] = 0.0
    L[1:-1] = c
    a = L[:-1]
    b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    mx = L.max()
    if mx <= 0:
        return None
    return num / (s * s * mx), L, s, mx, num


def _R(h):
    p = _parts(h)
    return -1.0 if p is None else p[0]


def _grad(h, L, s, mx, num):
    n = h.size
    a = L[:-1]
    b = L[1:]
    dL = np.zeros_like(L)
    dL[:-1] += (2.0 * a + b) / 3.0
    dL[1:] += (a + 2.0 * b) / 3.0
    gL = dL[1:-1]
    c1 = np.convolve(gL, h[::-1])
    c2 = np.convolve(gL, h)
    dnum = c1[n - 1:2 * n - 1] + c2[n - 1:2 * n - 1]
    argmax = int(np.argmax(L))
    dmx = np.zeros(n)
    if 1 <= argmax <= 2 * n - 1:
        k = argmax - 1
        lo = max(0, k - n + 1)
        hi = min(n, k + 1)
        idx = np.arange(lo, hi)
        dmx[idx] = 2.0 * h[k - idx]
    s2mx = s * s * mx
    return (dnum * s2mx - num * (2.0 * s * mx + s * s * dmx)) / (s2mx * s2mx)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    def tl(margin=0.0):
        return time.process_time() < deadline - margin

    rng = np.random.default_rng(424242 + int(budget_seconds * 1013))

    state = {"best": None, "bestR": -1.0}

    def consider(h):
        h = np.asarray(h, dtype=float).ravel()
        if h.size == 0 or h.size > 50000:
            return False
        h = np.maximum(h, 0.0)
        if h.sum() <= 0:
            return False
        r = _R(h)
        if r > state["bestR"]:
            state["bestR"] = r
            state["best"] = h.copy()
            return True
        return False

    if start is not None:
        consider(start)

    def symmetrize(h):
        h = np.asarray(h, dtype=float)
        n = h.size
        if n < 3:
            return h.copy()
        return 0.5 * (h + h[::-1])

    def push_sym(h):
        # push toward symmetric while preserving positivity
        s = symmetrize(h)
        return np.maximum(0.5 * h + 0.5 * s, 1e-15)

    def lbfgs_polish(seed, dl, maxfun=400, sym_weight=0.0):
        h0 = np.maximum(np.asarray(seed, dtype=float).copy(), 0.0)
        if h0.sum() <= 0:
            return h0
        base_scale = h0.max()
        if base_scale <= 0:
            return h0
        z0 = np.log(np.maximum(h0 / base_scale, 1e-11))
        n = h0.size
        rev_idx = np.arange(n - 1, -1, -1)

        def negR_grad(z):
            if time.process_time() >= dl:
                raise TimeoutError
            hh = np.exp(z) * base_scale
            p = _parts(hh)
            if p is None:
                return 1e10, z * 0.0
            r, L, s, mx, num = p
            g = _grad(hh, L, s, mx, num)
            gz = -g * hh
            if sym_weight > 0.0:
                # penalize asymmetry: h - h_rev
                diff = hh - hh[rev_idx]
                pen = sym_weight * np.sum(diff * diff) / (np.sum(hh * hh) + 1e-30)
                gz = gz + 4.0 * sym_weight * diff / (np.sum(hh * hh) + 1e-30) * hh
                return -(r - pen), gz
            return -r, gz

        try:
            res = minimize(negR_grad, z0, jac=True, method="L-BFGS-B",
                           options={"maxiter": maxfun, "maxfun": maxfun,
                                    "ftol": 1e-20, "gtol": 1e-17})
            cand = np.exp(res.x) * base_scale
            if np.all(np.isfinite(cand)) and cand.sum() > 0:
                if _R(cand) > _R(h0):
                    return cand
                return cand if _R(cand) >= _R(h0) else h0
        except Exception:
            pass
