        consider(h)
    if state["best"] is not None and tl():
        h = lbfgs_polish(symmetrize(state["best"]), min(deadline, time.process_time() + budget_seconds * 0.08), maxfun=500)
        consider(h)

    # Phase B: interleave size sweep, sym push, and jitter.
    tried = {}
    stall = 0
    while tl(0.5) and state["best"] is not None and stall < 3:
        base = state["best"].copy()
        N0 = base.size
        gained = False
        # size sweep, ordered by proximity
        ds = sorted([d for d in range(-30, 31) if d != 0], key=abs)
        for d in ds:
            M = N0 + d
            if M < 20 or M > 50000:
                continue
            if tried.get(M, 0) >= 2:
                continue
            tried[M] = tried.get(M, 0) + 1
            if not tl(0.5):
                break
