            if consider(hc):
                gained = True
        if not tl(0.5):
            break
        # symmetric refinement of the current best
        if tl(0.5):
            hp = push_sym(state["best"])
            hs = lbfgs_polish(hp, min(deadline, time.process_time() + 0.5), maxfun=300, sym_weight=0.02)
            if consider(hs):
                gained = True
        if not gained:
            for sigma in (0.002, 0.005, 0.01, 0.02, 0.04):
                if not tl(0.5):
                    break
                jit = state["best"] * (1.0 + sigma * rng.standard_normal(state["best"].size))
                jit = np.maximum(jit, 1e-15)
                if jit.sum() > 0:
                    hj = lbfgs_polish(jit, min(deadline, time.process_time() + 0.4), maxfun=220)
                    if consider(hj):
                        gained = True
                        break
        if not gained:
            # single-knot perturbation
            hb = state["best"].copy()
            n = hb.size
            for _ in range(8):
