        h = np.maximum(np.asarray(seed, dtype=float).copy(), 0.0)
        if h.sum() <= 0:
            return h
        best = h.copy()
        bestR = _R(best)
        n = h.size
        for r in range(rounds):
            if time.process_time() >= dl:
                break
            p = _parts(best)
            if p is None:
                break
            _, L, s, mx, num = p
            argmax = int(np.argmax(L))
            k = argmax - 1
            lo = max(0, k - n + 1)
            hi = min(n, k + 1)
            if hi <= lo:
                break
            span = hi - lo
            w = max(2, span // 6)
            cand_idx = np.arange(max(0, lo - w), min(n, hi + w))
