                x = np.linspace(-1, 1, n)
                trial = np.maximum(trial * (1.0 + scale * 0.5 * np.cos(0.5 * np.pi * x)), 0.0)
                if trial.sum() > 0:
                    rt = _R(trial)
                    if rt > bestR + 1e-16:
