            tried[M] = tried.get(M, 0) + 1
            if not tl():
                break
            xi = np.linspace(0, 1, N0)
            xo = np.linspace(0, 1, M)
            cand = np.interp(xo, xi, base)
            hc = lbfgs_polish(cand, min(deadline, time.process_time() + 0.6), maxfun=280)
            if consider(hc):
                gained = True
            if tl():
                hr = refine_peak(state["best"], min(deadline, time.process_time() + 0.35))
                if consider(hr):
                    gained = True
        if not tl():
            break
        if not gained:
            for sigma in (0.0015, 0.003, 0.006, 0.012, 0.025, 0.05):
                if not tl():
                    break
                jit = state["best"] * (1.0 + sigma * rng.standard_normal(state["best"].size))
