        n = h.size
        m = (n + 1) // 2
        half = h[:m].copy()
        base_scale = half.max()
        if base_scale <= 0:
            return h
        if use_log:
            z0 = np.log(np.maximum(half / base_scale, 1e-12))
        else:
            z0 = half / base_scale

        def build(z):
            hv = (np.exp(z) if use_log else np.maximum(z, 0.0)) * base_scale
            if n % 2 == 0:
                return np.concatenate([hv, hv[::-1]])
            return np.concatenate([hv, hv[-2::-1]])

        def negR_grad(z):
            if time.process_time() >= dl:
                raise TimeoutError
            full = build(z)
            p = _parts(full)
            if p is None:
                return 1e10, z * 0.0
            r, L, s, mx, num = p
            g = _grad(full, L, s, mx, num)
            gh = g[:m].copy()
            if n % 2 == 0:
                gh += g[m:][::-1]
            else:
                gh[:-1] += g[m:][::-1]
            dh = (np.exp(z) if use_log else np.ones_like(z)) * base_scale
            return -r, -gh * dh

