            if time.process_time() >= dl:
                raise TimeoutError
            hh = np.exp(z) * base_scale
            p = _parts(hh)
            if p is None:
                return 1e10, z * 0.0
            r, L, s, mx, num = p
            g = _grad(hh, L, s, mx, num)
            return -r, -g * hh

        try:
            res = minimize(negR_grad, z0, jac=True, method="L-BFGS-B",
                           options={"maxiter": maxfun, "maxfun": maxfun,
                                    "ftol": 1e-20, "gtol": 1e-16})
            cand = np.exp(res.x) * base_scale
            if np.all(np.isfinite(cand)) and cand.sum() > 0:
                if _R(cand) > _R(h):
                    return cand
        except Exception:
            pass
        return h

    if state["best"] is None:
        for N in (200, 260, 300, 337, 355):
            x = np.linspace(-1, 1, N)
            for taper in (0.3, 0.5, 0.7):
                t = np.clip((1 - np.abs(x)) / taper, 0, 1)
                consider(t)
            consider(np.exp(-3 * x ** 2))
            consider(np.ones(N))

