        if h.sum() <= 0:
            return h, -1.0
        h /= h.sum()
        p = _parts(h)
        if p is None:
            return h, -1.0
        R, L, s, mx, num = p
        g = _grad(h, L, s, mx, num)
        g = g - g.mean()
        hprev = h.copy(); gprev = g.copy()
        step = 1e-3
        stall = 0
        it = 0
        while it < max_iter and time.process_time() < dl:
            it += 1
            dh = h - hprev
            dg = g - gprev
            denom = float(np.dot(dg, dg))
            if denom > 1e-30:
