                trial /= st
                rt = _R(trial)
                if rt > R + 1e-16:
                    hprev, gprev = h, g
                    h, R = trial, rt
                    p = _parts(h)
                    if p is None:
                        break
                    R, L, s, mx, num = p
                    g = _grad(h, L, s, mx, num)
                    g = g - g.mean()
                    step *= 1.5
                    improved = True
                    stall = 0
                    break
                step *= 0.5
            if not improved:
                stall += 1
                if stall >= 25:
