        for N in (200, 260, 300, 337, 363):
            for taper in (0.3, 0.5, 0.7):
                for power in (0.5, 1.0, 1.5):
                    x = np.linspace(-1, 1, N)
                    t = np.clip((1 - np.abs(x)) / taper, 0, 1)
                    consider(t ** power)

