                hb, rb = bb_grad(cand, min(deadline, time.process_time() + 0.35))
                if rb > state["bestR"]:
                    state["best"], state["bestR"] = hb, rb
                    gained = True
            if tl():
                hc = lbfgs_polish(state["best"], min(deadline, time.process_time() + 0.5), maxfun=280)
                if consider(hc):
                    gained = True
        if not tl():
            break
        if not gained:
            for sigma in (0.001, 0.002, 0.004, 0.008, 0.016, 0.032, 0.064):
                if not tl():
                    break
                jit = state["best"] * (1.0 + sigma * rng.standard_normal(state["best"].size))
                jit = np.maximum(jit, 0.0)
                if jit.sum() > 0:
                    hj = lbfgs_polish(jit, min(deadline, time.process_time() + 0.5), maxfun=240)
