            break

    # Phase C: long final BB + L-BFGS alternation
    for _ in range(4):
        if state["best"] is None or not tl():
            break
        if tl():
            h, r = bb_grad(state["best"], min(deadline, time.process_time() + 1.5))
            if r > state["bestR"]:
                state["best"], state["bestR"] = h, r
        if tl():
            hc = lbfgs_polish(state["best"], min(deadline, time.process_time() + 2.0), maxfun=1500)
            consider(hc)

    if state["best"] is not None and tl():
        hc = lbfgs_polish(state["best"], deadline, maxfun=3000)
        consider(hc)

    best = state["best"]
    if best is None:
        best = np.ones(50)
    return np.asarray(best, dtype=float)

