            h2 = grad_ascent(state["best"],
                             min(deadline, time.process_time() + budget_seconds * 0.10),
                             steps=400)
            consider(h2)

    # Phase B: N sweep with polish
    tried = {}
    while tl() and state["best"] is not None:
