                  40, -40, 50, -50):
            M = N0 + d
            if M < 20 or M > 50000:
                continue
            if tried.get(M, 0) >= 2:
                continue
            tried[M] = tried.get(M, 0) + 1
            if not tl():
                break
            xi = np.linspace(0, 1, N0)
            xo = np.linspace(0, 1, M)
            cand = np.interp(xo, xi, base)
            hc = lbfgs_polish(cand, min(deadline, time.process_time() + 0.7),
                              maxfun=600)
            if consider(hc):
                gained = True
        if not tl():
            break
        if not gained:
            # gradient ascent from best, then log-space jitter
            if tl():
                ha = grad_ascent(state["best"],
                                 min(deadline, time.process_time() + 0.5),
                                 steps=150)
                if consider(ha):
                    gained = True
            for sigma in (0.001, 0.002, 0.004, 0.008, 0.016, 0.03, 0.05):
                if not tl() or gained:
                    break
                jit = state["best"] * np.exp(sigma * rng.standard_normal(state["best"].size))
                jit = np.maximum(jit, 0.0)
                if jit.sum() > 0:
                    hj = lbfgs_polish(jit, min(deadline, time.process_time() + 0.6),
                                      maxfun=350)
                    if consider(hj):
                        gained = True
                        break
        if not gained and len(tried) > 400:
            break

    # Phase C: final gradient ascent + long polish
    if state["best"] is not None and tl():
        hc = grad_ascent(state["best"], deadline, steps=600)
        consider(hc)
    if state["best"] is not None and tl():
        hc = lbfgs_polish(state["best"], deadline, maxfun=4000, gtol=1e-18)
        consider(hc)

    best = state["best"]
    if best is None:
        best = np.ones(50)
    return np.asarray(best, dtype=float)

