                  10, -10, 12, -12, 15, -15, 20, -20, 28, -28, 40, -40):
            M = N0 + d
            if M < 20 or M > 50000:
                continue
            if tried.get(M, 0) >= 2:
                continue
            tried[M] = tried.get(M, 0) + 1
            if not tl():
                break
            xi = np.linspace(0, 1, N0)
            xo = np.linspace(0, 1, M)
            cand = np.interp(xo, xi, base)
            hc = polish(cand, min(deadline, time.process_time() + 0.6), maxfun=320)
            if consider(hc):
                gained = True
        if not tl():
            break
        if not gained:
            for sigma in (0.0015, 0.003, 0.006, 0.012, 0.025, 0.05):
                if not tl():
                    break
                jit = state["best"] * (1.0 + sigma * rng.standard_normal(state["best"].size))
                jit = np.maximum(jit, 0.0)
                if jit.sum() > 0:
                    hj = polish(jit, min(deadline, time.process_time() + 0.5), maxfun=260)
                    if consider(hj):
                        gained = True
                        break
        if not gained and len(tried) > 300:
            break

    # Phase C: long polish then coordinate climb.
    if state["best"] is not None and tl():
        hc = polish(state["best"], min(deadline, time.process_time() + budget_seconds * 0.25), maxfun=3000)
        consider(hc)
    if state["best"] is not None and tl():
        hc = coord_climb(state["best"], deadline, sweeps=6)
        consider(hc)

    best = state["best"]
    if best is None:
